stop();
Flux<TelemetrySample> stream = eventBus.stream();
recordSubscription = stream
        .concatMap(sample -> Mono.defer(() -> eventLogService.record(sample)).onErrorResume(error -> Mono.empty()))
        .subscribe(unused -> { }, error -> { });
reconcileSubscription = reorderingService.windows(stream)
        .concatMap(sample -> Mono.defer(() -> eventLogService.reconcile(sample)).onErrorResume(error -> Mono.empty()))
        .subscribe(unused -> { }, error -> { });
